from pathlib import Path
import re,json,shutil
ROOT=Path(__file__).resolve().parents[1]
MOD=ROOT/'s1/b6-my-digital-workspace'
REF=ROOT/'s1/b5-search-save-cite'
def bi(zh,en): return f'<span class="zh">{zh}</span><span class="en">{en}</span>'
def p(zh,en,cls=''): return f'<p'+(f' class="{cls}"' if cls else '')+'>'+bi(zh,en)+'</p>'
def h(n,zh,en): return f'<h{n}>'+bi(zh,en)+f'</h{n}>'
def a(url,zh,en): return f'<a href="{url}">'+bi(zh,en)+'</a>'
def links(items):return '<div class="q-links">'+''.join(a(*x) for x in items)+'</div>'
TIERS=[('base','base-camp.html','bc-list',8,3),('ridge','ridge.html','rg-list',3,1.5),('summit','summit.html','sm-list',3,.5)]
DEF='<script type="application/json" id="quest-def">'+json.dumps({'tiers':[dict(zip(['id','page','list','total','pts'],t)) for t in TIERS]})+'</script>'
nav='<nav aria-label="Module 本单元">'+''.join(a(*x) for x in [('index.html','任务地图','Quest map'),('base-camp.html','⛺ 起点营地','⛺ Base Camp'),('ridge.html','🧭 山脊','🧭 Ridge'),('summit.html','🚩 登顶','🚩 Summit'),('rubric.html','量规','Rubric'),('quiz.html','自测','Quiz')])+'</nav>'
ref=(REF/'base-camp.html').read_text(encoding='utf-8')
head=ref.split('<main id="main">')[0]
head=re.sub(r'<script type="application/json" id="quest-def">.*?</script>',DEF,head,flags=re.S)
head=re.sub(r'<nav aria-label="Module 本单元">.*?</nav>',nav,head,flags=re.S)
head=head.replace('B5','B6')
foot='</main><footer class="site">Digital Learning 数字化学习 · 公开课程 A public course · 第一学期 B6</footer><script src="../../assets/lang.js"></script><script src="../../assets/checklist.js"></script><script src="../../assets/quest.js"></script></body></html>'
def write(name,titlezh,titleen,body,role='tier'):
 s=head
 s=re.sub(r'<title.*?</title>',f'<title data-zh="{titlezh} · B6 我的数字工作台" data-en="{titleen} · B6 My Digital Workspace">{titleen} · B6 My Digital Workspace</title>',s,flags=re.S)
 s=re.sub(r'<meta name="description"[^>]*>',f'<meta name="description" content="B6 我的数字工作台：{titlezh}。 My Digital Workspace: {titleen}.">',s)
 s=re.sub(r'<meta name="dl-page-role"[^>]*>',f'<meta name="dl-page-role" content="{role}">',s)
 s=s.replace(f'href="{name}">',f'href="{name}" aria-current="page">')
 (MOD/name).write_text(s+'<main id="main">\n'+body+'\n'+foot,encoding='utf-8')
def step(n,kind,zh,en,mins,body):return f'<li class="q-step"><div class="q-step-n"><b>{n}</b></div><h3><span class="q-kind {kind}">'+bi({'learn':'学','practice':'练','make':'做','submit':'交','reflect':'思'}[kind],kind.upper())+'</span> '+bi(zh,en)+'<span class="q-mins">'+bi(f'{mins} 分钟',f'{mins} min')+'</span></h3><div class="q-step-body">'+body+'</div></li>'
def checklist(id,items):return f'<ul class="checklist" id="{id}">'+''.join(f'<li><input type="checkbox" id="{id}{i}"><label for="{id}{i}">'+bi(*t)+'</label></li>' for i,t in enumerate(items,1))+'</ul>'
def tierhead(id,zh,en,pts,mins):
 badge={'base':'base-camp','ridge':'ridge','summit':'summit'}[id]
 return f'<div class="q-tier-head"><img src="../../assets/img/quest/badge-{badge}.svg" alt=""><div>'+p('B6 · 第 7 周','B6 · Week 7','kicker')+h(1,zh,en)+'</div></div><div class="meta"><span class="tag">'+bi(pts+' 分',pts+' pts')+'</span><span class="tag time">'+bi(f'约 {mins} 分钟',f'~{mins} min')+'</span><span class="tag">'+bi('🚫 独立','🚫 Independent')+'</span></div>'
privacy=p('发布前：不放真名、正脸照片、学校全名或可定位的信息。屏幕里隐藏邮箱、通知和别人的日程。若误放，先撤下或遮盖，再发布；不因隐私失误扣分。','Before publishing: no real names, face photos, full school names or locating details. Hide email addresses, notifications and other people’s appointments. If anything slips through, remove or mask it and republish; privacy slips cost no points.')
independent=p('本周不使用生成式 AI；清单和选课理由由自己写。家长一起挑时段、讨论选课，欢迎。新注册先告诉家长；需要手机号时，先征得家长同意。共用电脑用完登出。','No generative AI this week; write your inventory and course reasons yourself. Parents may help weigh choices and study times. Tell a parent before new registrations; obtain their agreement before supplying a phone number. Sign out after using a shared computer.')
nextmod=links([('../m1-what-is-learning/index.html','下一单元：M1 什么是学习 →','Next module: M1 What is Learning? →')])
faq=h(2,'常见问题','FAQ')+'<details><summary>'+bi('没有云盘、U 盘或第二台设备？','No cloud drive, USB stick or second device?')+'</summary>'+p('独立副本指不会随着工作文件的修改或删除一起变化的副本：发给自己的附件、不与工作文件夹同步的云端位置，或已有的其他存储位置。相同同步文件夹中的副本、单纯同步都不算。无需购买或安装；没有第二台设备，照样从独立副本打开检查。电脑同盘的非同步练习副本可用于本周练习，但不能防设备损坏，应另外备份重要文件。视频太大又无其他位置？备份页面正文，注明视频原文件存放位置即可；这不是视频的独立备份，以后有条件再补。','An independent copy does not change when the working file is edited or deleted: an emailed attachment, cloud storage not synced with the working folder, or other storage already available. A copy in the same synced folder, or sync alone, does not count. No purchase or installation is needed; open the independent copy even without a second device. An unsynced practice copy on the same disk works for this week’s exercise, but cannot protect against device failure; back up important work separately. Video too large and no other location? Back up the page text and state where the original video lives; that is not an independent video backup, and you can add one when feasible.')+'</details><details><summary>'+bi('上周没写选课理由，或这周改主意了？','No course reason from last week, or changed your mind?')+'</summary>'+p('有上周理由就引一句，再写现在的决定；试学小记也可用。不需要补做 B5 山脊。找不到旧理由，就重读菜单介绍，写“本周补记”及自己的具体理由；不编造旧记录。换课同样达标。','Quote a prior course-pick reason or sampling note, then give your current decision. B5 Ridge is not required. If no prior note exists, reread the menu and label your own specific reason “added this week”; never invent a past record. Changing courses earns the same credit.')+'</details><details><summary>'+bi('节假日、卡住或想补交？','A holiday, a problem, or a revision?')+'</summary>'+p('假期不安排新任务或截止日期；有冲突顺延到下一个工作日。按自己的速度完成，迟交不扣分；更新后邮件导师，附链接与已打码截图，问题通常 24–48 小时回复；分数与一条建议在一周内回复（见量规）。答疑预约方式与平台见开课信。','No new tasks or deadlines on university holidays; shift conflicting work to the next working day. Work at your pace; no late penalty. Email your mentor after updating, with links and a masked screenshot if needed; questions usually receive replies in 24–48 hours; scores and one suggestion arrive within a week (see rubric). The welcome letter supplies the video-help booking route and platform.')+'</details>'
# Keep the existing course-created diagram, including its public anchor.
old=(MOD/'index.html').read_text(encoding='utf-8')
mapfig=re.search(r'<figure id="workspace-map-figure".*?</figure>',old,re.S).group(0)
mapfig=mapfig.replace('微课 1–4 各给出免费、诚实的选项','微课 1–3 给出免费选项（备份见微课 1）').replace('micro-lessons 1–4 lay out the free, honest options','micro-lessons 1–3 lay out free options (backup is in lesson 1)').replace('备份是后悔药','备份提供独立副本').replace('backup as the cure for regret','backup as an independent copy').replace('后悔药','独立副本').replace('the cure for regret','an independent copy')
status=re.search(r'<div class="q-status" data-quest-status>.*?</div>\s*<h2>',(REF/'index.html').read_text(encoding='utf-8'),re.S).group(0).rsplit('<h2>',1)[0]
hero='<div class="q-hero"><img src="../../assets/img/quest/quest-banner.svg" alt="" width="960" height="320"><div class="q-hero-text">'+p('第一学期 · 第 7 周 · B6','Semester 1 · Week 7 · B6','q-label')+h(1,'我的数字工作台','My Digital Workspace')+p('把文件、时间与笔记安排好，为下一阶段的学习做好准备。','Organise your files, time and notes for the next stage of learning.')+'</div></div>'
carddata=[('base','起点营地','Base Camp','3 · 及格线','3 · pass mark',80,[('搭好四角，写四行工作台记录','Set up four corners; write a four-line workspace record'),('写 B1–B6 基本功清单（六行）','Write the six-line B1–B6 inventory'),('发布选课页：主修 + 探索、理由、时段','Publish course choices: core + explore, reasons, study slot'),('发布、登记两个链接、备份、写日志','Publish, register two links, back up, write your log')]),('ridge','山脊','Ridge Trail','+1.5 → 4.5','+1.5 → 4.5',25,[('学快捷键与视频通话礼仪','Learn shortcuts and video-call manners'),('录约 1 分钟导览，展示四角','Record a ~1-minute tour of all four corners'),('更新作品集，通知导师','Update the Portfolio; notify your mentor')]),('summit','登顶','Summit','+0.5 → 5','+0.5 → 5',15,[('用无隐私的练习文件测试恢复','Test recovery with a non-private practice file'),('写实测结果和下次备份规则','Record the result and your next backup rule'),('更新原页，通知导师','Update the same page; notify your mentor')])]
cards='<div class="q-tiers">'
for id,zh,en,ptz,pte,mins,items in carddata:
 page={'base':'base-camp.html','ridge':'ridge.html','summit':'summit.html'}[id]; badge={'base':'base-camp','ridge':'ridge','summit':'summit'}[id]
 cards+=f'<section class="q-tier {id}" data-tier="{id}"><div class="q-tier-top"><img class="q-on" src="../../assets/img/quest/badge-{badge}.svg" alt=""><img class="q-off" src="../../assets/img/quest/badge-'+('base-camp' if id=='base' else 'locked')+'.svg" alt=""><div>'+p('必做' if id=='base' else '选做挑战','Required' if id=='base' else 'Optional challenge','q-label')+h(3,zh,en)+'</div></div><div class="q-tier-body"><div class="q-tier-meta"><span class="q-chip pts">'+(bi('3 分 · 及格线','3 pts · pass mark') if id=='base' else bi(ptz+' 分',pte+' pts'))+'</span><span class="q-chip time">'+bi(f'{mins} 分钟',f'{mins} min')+'</span><span class="q-chip q-done">'+bi('✓ 清单完成','✓ Checklist done')+'</span></div><ul>'+''.join('<li>'+bi(*t)+'</li>' for t in items)+'</ul>'
 if id!='base':cards+='<p class="q-lock">'+bi('先完成前一关的清单；随时可预览。本地勾选不决定分数。','Finish the earlier checklist first; preview anytime. Local ticks do not decide your score.')+'</p>'
 cards+=f'<a class="q-btn" href="{page}">'+bi('打开步骤 →','Open the steps →')+'</a></div></section>'
cards+='</div>'
rules=h(2,'三关怎么玩','How the tiers work')+p('起点营地达标得 3 分，是 5 分里的及格线；山脊、登顶选做。导师按量规评分：起点营地至少 2 分才计山脊；山脊至少 1 分才计登顶。公开学习者用同一量规自评。','Base Camp meeting the rubric earns 3 of 5 points, the pass mark; Ridge and Summit are optional. Mentors score with the rubric: Base Camp must earn at least 2 before Ridge counts; Ridge at least 1 before Summit counts. Open learners self-score with the same rubric.')+p('总预算 80 + 25 + 15 = 120 分钟，含指定视频片段、发布和日志；自测及拓展另为选做。两份交付：作品集中的工作台记录与清单，以及单独的“我的外部课程”页。挑战只更新原作品集页。','The budget is 80 + 25 + 15 = 120 minutes, including the specified clips, publishing and log. Quiz and extensions are optional extras. Two deliverables: the workspace record and inventory on your Portfolio, and a separate “My external course” page. Challenges update the same Portfolio page.')+p('徽章来自本浏览器的清单，表示已准备好接受评分；它不是成绩，也不会跨设备同步。山路只是任务顺序的比喻，勾选不代表实际掌握。','Badges come from this browser’s checklists and mean ready for review; they are not grades and do not sync across devices. The mountain stands for task order; ticking a box does not demonstrate mastery.')
write('index.html','任务地图','Quest map',hero+'<div class="meta"><span class="tag">5 pts</span><span class="tag">'+bi('≤ 120 分钟 · 🚫 独立','≤ 120 min · 🚫 Independent')+'</span></div>'+status+h(2,'这周做什么？从起点营地开始','What this week? Start at Base Camp')+cards+rules+'<div class="card note" id="ai">'+h(2,'独立与隐私','Independent work and privacy')+independent+privacy+'</div>'+h(2,'工作台四角','Four corners of the workspace')+mapfig+links([('rubric.html','评分量规','Scoring rubric'),('quiz.html','选做自测','Optional self-quiz'),('want-more.html','选做拓展','Optional extensions'),('media/handouts/basics-checklist.html','基本功清单讲义','Basics inventory handout')])+nextmod,'quest-map')
# Base: essential downstream work stays here.
steps=[]
steps.append(step(1,'practice','先找一个旧文件','Find one old file first',1,p('找上周的检索报告或任一旧课程文件，记下花了几秒；没找到也如实记。稍后整理后再找一次。','Find last week’s search report or any old course file. Note the seconds; if it is missing, say so. Try again after organising.')))
steps.append(step(2,'learn','读三段微课','Read three micro-lessons',15,p('每页约 5 分钟，先看页面指定的视频片段，再读文字。工具打不开时走页面给出的兜底路线，不用安装新软件。','Allow ~5 minutes each: watch the specified part of the clip, then read the text. If a tool is unavailable, use the lesson’s fallback; no new software is needed.')+links([('lesson-1-cloud-and-sync.html','微课 1 · 云盘与同步','Lesson 1 · Cloud and sync'),('lesson-2-calendar-and-reminders.html','微课 2 · 日历与提醒','Lesson 2 · Calendar and reminders'),('lesson-3-notes-that-stay.html','微课 3 · 留得住的笔记','Lesson 3 · Notes that stay')])) )
steps.append(step(3,'practice','搭好工作台四角','Set up all four corners',17,p('文件：建作业、网站备份、笔记三个文件夹，把课程文件归位。时间：设“外部课程 · 一小时”的每周提醒，提前 10 分钟响，起点为第 11 周；时段与选课页一致。笔记：用已有工具固定一个落点，存一条带三行来源的笔记。备份：把上周报告另存一份到原工作位置之外（邮箱附件或已有备份位置），打开副本确认可读。不要把自动同步当备份。','Files: create assignments, site-backups and notes folders; move course files into place. Time: set a weekly “External course · one hour” reminder, 10 minutes ahead, starting in Week 11; match your choice page’s slot. Notes: choose one existing tool and save one note with three source lines. Backup: save last week’s report outside its working location (email attachment or an existing backup location), then open the copy. Automatic sync alone is not backup.')+p('不用购买 U 盘或找第二台设备；从原位置之外打开独立副本即可。只整理课程文件。整理后再找第 1 步的文件，记下秒数。','You need not buy a USB stick or find a second device; open an independent copy outside its original location. Organise only course files. Find step 1’s file again and record the seconds.')))
steps[-1]=steps[-1].replace('</div></li>', links([('../../calendar.html','查看课程周次日历','See the course-week calendar'),('activity-workspace-rehearsal.html','选读：分步跟做（不用重复）','Optional: guided walkthrough (do not repeat)')])+p('在校学生按开课信确认第 11 周日期；公开学习者以自己开始 M3 外部课程学习的那一周为起点。假期当天不学：碰到时将该次学习与提醒顺延到下一个工作日，不用现在编辑整学期。','Enrolled students use the welcome letter to confirm Week 11’s date; open learners use the week they begin M3 external-course study. Keep holidays free: when an occurrence falls on one, move that session and reminder to the next working day; you need not edit a whole term now.')+'</div></li>')
steps.append(step(4,'make','写四行工作台记录','Write a four-line workspace record',7,p('作品集页新建“我的数字工作台”区块，照下面四行用自己的话写；不需要截图或录屏。记录刚才真正做过的动作，别只列软件名字。','Add “My digital workspace” to your Portfolio. Write the four lines below in your own words; screenshots and recording are not required here. Describe what you actually did, rather than just naming apps.')+'<div class="card">'+bi('① 文件：放在哪里？我怎样找到那个旧文件？<br>② 时间：每周哪一时段、从第几周开始、提前多久提醒？<br>③ 笔记：固定落点在哪里？刚存了什么学习笔记？<br>④ 备份：备份了什么、放在哪里、打开副本的结果？再写一句发布后备份规则。（别写私人路径或邮箱）','① Files: where do they live, and how did I find the old file?<br>② Time: weekly slot, start week, reminder lead time?<br>③ Notes: fixed home and the learning note just saved?<br>④ Backup: what was copied, where, and what happened when I opened it? Add your post-publish backup rule. (No private paths or email addresses.)')+'</div>'))
steps.append(step(5,'make','基本功清单六行','Six inventory lines',8,p('接在四行记录后，B1–B6 各一行：“扎实 + 一句真实例子”或“还不稳 + 一句具体困难”。两种状态同分。六个技能依次是：邮件与截图、录屏与网站、翻译核对、账号与命名、检索与来源卡、工作台。','After the record, add one line each for B1–B6: “solid + one real example” or “still shaky + one specific difficulty.” Both states earn equal credit. Skills in order: email and screenshots; recording and website; checking translation; accounts and naming; search and source cards; workspace.')+links([('media/handouts/basics-checklist.html','打开自查讲义','Open the self-check handout')])))
steps.append(step(6,'make','我的外部课程：三段','My external course: three paragraphs',15,p('在自己的网站单独建“我的外部课程”页。① 哪两门：主修 + 探索，写全课名；探索最多 1 小时、两三节。② 为什么：引用 B5 的一句选课理由或试学小记，加一句现在的想法；若旧记录缺失，重读菜单，标“本周补记”写具体理由。换课可以，不必试学过。③ 什么时候：固定时段，与第 11 周起（公开学习者：开始 M3 的那一周）的每周提醒一致。','Create a separate “My external course” page on your site. ① Which two: give the full core and explore course names; explore takes at most one hour, two or three lessons. ② Why: quote a B5 course-pick reason or sampling note and add your current thinking; if no prior record exists, reread the menu and label a specific reason “added this week.” Changes are welcome; prior sampling is not required. ③ When: a fixed slot matching your weekly reminder from Week 11 (open learners: the week you begin M3).')+p('菜单外的课逐条核对：免费、当地能打开、本学期非 AI 主题、时长合规、注册方式清楚；选择页写明理由。在校学生发导师确认，公开学习者自行核对。','For an off-menu choice, check all five rules: free, accessible locally, not AI-themed this semester, within duration limits, and clear registration requirements. State reasons on the page. Enrolled students send it to their mentor for confirmation; open learners check it themselves.')+links([('../../external-courses.html','打开课程菜单与完整规则','Open the course menu and full rules')])))
steps.append(step(7,'submit','发布、登记、备份','Publish, register, back up',13,privacy+p('发布作品集和选课页，用访客模式确认两页可读；两个链接登记到导师登记表（B6）。公开学习者把两个链接发给自己。发布后把两页正文各另存一份到原工作位置之外，打开确认；无需为备份确认再改原文，在本页清单确认即可。','Publish your Portfolio and choice page; check both as a visitor. Register both links on your mentor’s tracking sheet (B6). Open learners email both links to themselves. After publishing, save both page texts outside the working location and open them to check; confirm this in this page’s checklist; no edit to the published record is needed.')))
steps.append(step(8,'reflect','三行日志','Three-line log',4,p('日志页写：① 整理前后找同一文件各用了几秒，学到了什么？② 还有哪里卡住？③ 你认为“学习”是什么？给出一件亲身经历，留给下周 M1。下次更新日志后也备份。','On your log page: ① Seconds to find the same file before and after; what did you learn? ② What still troubles you? ③ What do you think “learning” means? Give one personal experience for next week’s M1. Back up the log after updating it.')))
baseitems=[('读完微课 1–3。','I finished lessons 1–3.'),('四角已搭好，旧文件重找过，独立副本已打开。','All four corners are set; I found the old file again and opened the independent copy.'),('作品集有四行具体工作台记录。','My Portfolio has four specific workspace-record lines.'),('B1–B6 各一行：状态 + 具体例子或困难。','Each B1–B6 inventory line has a status and a specific example or difficulty.'),('选课页三段齐全，主修、探索、理由与时段写清。','My choice page has both courses, reasons and the fixed slot in three paragraphs.'),('提醒从第 11 周起（公开学习者：开始 M3 的那一周），时段与选择页一致。','My reminder starts in Week 11 (open learners: the week I begin M3) and matches my choice-page slot.'),('两页隐私已检查、已发布、两链接已登记（公开学习者：已发给自己）、发布后已备份。','Both pages are privacy-checked, published and backed up; both links are registered (open learners: emailed to myself).'),('三行日志已发布并备份。','My three-line log is published and backed up.')]
write('base-camp.html','起点营地','Base Camp',tierhead('base','起点营地','Base Camp','3',80)+'<div class="card">'+p('必做：作品集一处（四行工作台记录 + 六行基本功清单），另加一页“我的外部课程”。无需录屏也能达标得 3 分；录屏在山脊。','Required: a Portfolio section (four-line workspace record + six-line inventory), plus a separate “My external course” page. Full Base Camp earns 3 points without a recording; the tour is on the Ridge.')+'</div>'+h(2,'八个步骤','Eight steps')+'<ol class="q-steps">'+''.join(steps)+'</ol>'+h(2,'起点营地清单','Base Camp checklist')+checklist('bc-list',baseitems)+'<div class="q-cheer" data-cheer="base" role="status">'+p('清单完成，准备好让导师按量规评分。可停在这里，下一站 M1；想继续就去山脊。','Checklist done: ready for your mentor’s rubric review. You may stop here and continue to M1, or try the Ridge.')+'</div>'+links([('rubric.html','查看量规','See the rubric'),('ridge.html','选做：上山脊 →','Optional: Ridge →')])+faq+nextmod)
# Ridge
rg=step(1,'learn','两段微课，练三个动作','Two micro-lessons, three moves',10,links([('lesson-4-keyboard-shortcuts.html','微课 4 · 快捷键','Lesson 4 · Shortcuts'),('lesson-5-video-call-manners.html','微课 5 · 视频通话礼仪','Lesson 5 · Video-call manners')])+p('每页约 5 分钟，含指定视频。读完微课 4，用复制、粘贴、撤销各练一次（Mac 看对应列）；读完微课 5，写一句答疑前要检查什么，放在导览旁。不需要真的预约或安装会议软件。','Allow ~5 minutes per page including its specified clip. After lesson 4, practise copy, paste and undo once each (Mac: use the matching column). After lesson 5, add one line beside your tour about what to check before a help call. No booking or meeting-software installation is required.'))
rg+=step(2,'make','录四角导览','Record the four-corner tour',10,privacy+p('约 1 分钟，只录屏幕、不露脸，声音可选。依次展示文件夹、那一条每周提醒、笔记落点、备份副本。只显示外部课程那一条日历，隐藏他人的事。回放检查隐私，不够清楚可重录；时长略有出入不扣分。手机自带录屏同样可用。','Aim for ~1 minute: screen only, no face, voice optional. Show your folders, the weekly reminder, notes home and backup copy. Show only the external-course calendar entry; hide other people’s events. Replay to check privacy and retake if unclear; a little over or under the target costs no points. Built-in phone recording works too.'))
rg=rg.rsplit('</div></li>',1)[0]+p('邮箱备份只展示打开的附件或另存的副本，不录收件箱列表、邮箱地址栏或其他邮件。','For an email backup, show only the opened attachment or saved copy, never the inbox list, email address bar or other messages.')+'</div></li>'
rg+=step(3,'submit','更新同一作品集页','Update the same Portfolio page',5,p('把视频和答疑准备那句话加在原作品集区块，访客模式确认视频可播。发布、备份视频与更新正文，给导师发“B6 已更新”及原链接；公开学习者发给自己。文件过大就用已有的视频托管并嵌入或链接，不要求注册新服务；先检查视频在访客模式可播。视频太大且无独立备份位置时，备份页面正文并注明视频原文件位置即可，不影响本关评分。','Add the video and help-call preparation sentence to your existing Portfolio section. Check playback as a visitor. Publish, back up the video and updated text, and email “B6 updated” with the original link to your mentor; open learners email themselves. For a large file, embed or link from video hosting you already use; no new service registration is required. Check visitor playback first. If the video is too large and no independent storage is available, back up the page text and state where the original video lives; this does not reduce the tier score.'))
write('ridge.html','山脊','Ridge Trail',tierhead('ridge','山脊','Ridge Trail','+1.5 → 4.5',25)+'<div class="q-gate" data-gate="ridge">'+p('先完成起点营地；这里随时可读。导师按量规计分，起点营地至少 2 分才计山脊。','Complete Base Camp first; this page is always readable. Ridge points count when Base Camp earns at least 2.')+'</div>'+p('本关交付：同一作品集里的四角屏幕导览 + 一句答疑准备。','Deliverable: a screen tour of all four corners plus one help-call preparation sentence on the same Portfolio page.')+'<ol class="q-steps">'+rg+'</ol>'+checklist('rg-list',[('两段微课读完，三个快捷键练过。','I read both lessons and practised the three shortcuts.'),('四角导览与答疑准备句已加到原作品集；回放检查无隐私。','My four-corner tour and preparation sentence are on the same Portfolio; playback has no private details.'),('访客可播、已发布备份、已通知导师（公开学习者：自己）。','Visitor playback works; I published, backed up and notified my mentor (open learners: myself).')])+'<div class="q-cheer" data-cheer="ridge" role="status">'+p('山脊清单完成，等待导师评分。想继续？安全恢复测试在登顶。','Ridge checklist complete, ready for review. Continue to the Summit for a safe recovery test.')+'</div>'+links([('index.html','← 任务地图','← Quest map'),('summit.html','选做：登顶 →','Optional: Summit →')])+faq+nextmod)
# Summit: safe failure/recovery rather than extra volume.
sm=step(1,'practice','只用练习文件测试','Test only a practice file',10,p('在一个临时练习文件夹新建 recovery-practice.txt，写“练习版 1”。另存独立副本到不随此文件同步的位置（如发给自己的附件）。打开副本确认能读。只在原练习文件把文字改成“练习版 2”，不要删除任何真实文件，也不要清空回收站。随后从独立副本恢复为另一个新文件 recovery-restored.txt，打开比较：是否仍有“练习版 1”？','In a temporary practice folder, create recovery-practice.txt containing “practice version 1.” Save an independent copy somewhere that does not sync with this file (for example, email it to yourself as an attachment). Open the copy. Change only the original practice file to “practice version 2”; delete no real work and do not empty the bin. Restore the independent copy as a new file, recovery-restored.txt. Open and compare: does it still contain “practice version 1”?')+p('没成功？如实记录在哪一步出问题、看到什么、下次怎么改；失败的实测与成功的实测同分。只读说明或写“我会备份”不算实测。','If it fails, honestly record the step, what you observed and what you would change. An attempted test that fails earns the same credit as a successful one. Reading instructions or writing “I will back up” is not an attempted test.'))
sm+=step(2,'make','写两句，发布更新','Write two sentences and publish',5,p('在原作品集加“恢复测试”：① 具体结果：我把什么从哪里恢复到了哪里，打开看见什么；若失败，写实际卡点。② 我的备份规则：何时备份、存到哪个独立位置、如何确认能打开；若失败，写下一次要改变的动作。发布、备份更新正文，给导师发“B6 已更新”与原链接；公开学习者发给自己。','Add “Recovery test” to the same Portfolio: ① Specific result: what I restored, from where to where, and what I saw on opening; if it failed, state the actual obstacle. ② My backup rule: when, which independent location, and how I will check it opens; if it failed, name the action to change next time. Publish, back up the updated text, and email “B6 updated” with the original link to your mentor; open learners email themselves.'))
write('summit.html','登顶','Summit',tierhead('summit','登顶','Summit','+0.5 → 5',15)+'<div class="q-gate" data-gate="summit">'+p('先完成山脊；这里随时可读。山脊至少 1 分才计登顶。','Finish the Ridge first; this page is always readable. Summit points count when Ridge earns at least 1.')+'</div>'+p('本关不比工具多少。用一个不含隐私的练习文件，实际检查独立副本能否恢复旧内容。','This tier tests whether an independent copy can recover earlier content, using one non-private practice file.')+'<ol class="q-steps">'+sm+'</ol>'+checklist('sm-list',[('我只用练习文件，实际尝试了独立副本与恢复。','I used only practice files and actually attempted an independent copy and restore.'),('我写了具体实测结果（成功或失败）和下一次备份规则。','I wrote the actual result (success or failure) and my next backup rule.'),('原作品集已更新备份、已通知导师（公开学习者：自己）。','I updated and backed up the Portfolio and notified my mentor (open learners: myself).')])+'<div class="q-cheer" data-cheer="summit" role="status">'+p('登顶清单完成。分数按量规，不按徽章。带着工作台进入 M1。','Summit checklist complete. The rubric determines points, not the badge. Bring your workspace to M1.')+'</div>'+links([('index.html','← 任务地图','← Quest map')])+faq+nextmod)
# Explicitly count omissions, with one group per evidence unit and no double-counting.
units=[('文件记录缺失，或没有具体整理/找回动作。','Files line missing, or no specific organising/retrieval action.'),('时间记录缺失，或没有与选择页一致、从第 11 周起（公开学习者：开始 M3 的那一周）的每周提醒。','Time line missing, or no matching weekly reminder starting in Week 11 (open learners: the week they begin M3).'),('笔记记录缺失，或没有固定落点与实际笔记。','Notes line missing, or no fixed home and actual note.'),('备份记录缺失；或缺打开独立副本的结果；或缺发布后备份规则（本组最多算一项；清单确认实际备份，不另扣分）。','Backup line missing; or independent-copy opening result missing; or post-publish backup rule missing (one omission maximum for this group; actual backup is confirmed in the checklist without a separate deduction).'),('六行清单不齐，或有行缺“状态 + 具体例子/困难”（整张清单最多算一个缺项）。','Inventory incomplete, or a line lacks status plus a specific example/difficulty (at most one omission for the whole inventory).'),('主修或探索课名缺失，或菜单外课没按五条规则说明、在校学生未发导师确认。','Core/explore name missing, or an off-menu course lacks the five-rule explanation or (enrolled students) has not been sent for mentor confirmation.'),('选课理由缺失或只剩“有趣”等形容词，没有自己的具体理由。','Course reason missing or just adjectives such as “interesting,” without a specific personal reason.'),('选课固定时段缺失或与提醒不一致（与时间记录的同一问题只算一次）。','Fixed choice-page slot missing or mismatched with the reminder (count the same scheduling issue only once across this and the time line).')]
body=p('B6 · 5 分 · 🚫 独立','B6 · 5 points · 🚫 Independent','kicker')+h(1,'三关怎么计分','How the three tiers score')+rules
body+='<div class="table-wrap"><table class="cards rubric"><tr class="head">'+''.join('<th>'+bi(*x)+'</th>' for x in [('关卡','Tier'),('达标','Meets'),('发展中','Developing'),('尚未达标 / 无证据','Not yet / no evidence')])+'</tr>'
rows=[('row1','起点营地 · 3 分','Base Camp · 3 pts',('3 · 两页链接可读，下面八组证据零缺项；登记不另扣分。','3 · Both pages readable; no omissions among the eight evidence groups below. Registration carries no deduction.'),('2 · 恰好一组缺项。','2 · Exactly one omitted group.'),('1 · 两组或更多缺项，但至少有一项可读的原创内容。0 · 没有可读的原创证据。未登记先联系补登记，已看到的证据照常计分。','1 · Two or more omitted groups, with at least some readable original work. 0 · No readable original evidence. If registration is missing, request it; score the evidence already available.')),
('row2','山脊 · +1.5 分','Ridge · +1.5 pts',('1.5 · 访客可播的导览，四角均清楚可辨；有一句具体的答疑前准备。','1.5 · Visitor-playable tour with all four corners identifiable, plus one specific help-call preparation sentence.'),('1 · 有可播导览但缺角；或导览四角齐但缺准备句。','1 · Playable tour missing corners, or all four shown but no preparation sentence.'),('0 · 没有可播导览（即使只有准备句），或未做本关。','0 · No playable tour (even if a preparation sentence exists), or this tier not attempted.')),
('row3','登顶 · +0.5 分','Summit · +0.5 pts',('0.5 · 实际尝试练习文件恢复；记录具体结果和下一次备份规则/改法。失败的如实实测与成功同分。','0.5 · Actually attempted recovery with a practice file; specific result and next backup rule/fix recorded. An honest failed attempt scores equally to a successful test.'),('不设部分分：两项证据齐全才计 0.5。','No partial credit: both evidence parts required.'),('0 · 未尝试，或缺具体结果，或缺备份规则/改法。','0 · No attempt, or specific result missing, or backup rule/fix missing.'))]
for id,zh,en,*cells in rows:body+=f'<tr id="{id}"><td><b>'+bi(zh,en)+'</b></td>'+''.join('<td>'+bi(*t)+'</td>' for t in cells)+'</tr>'
body+='</table></div>'+h(2,'起点营地：缺项怎么数','Base Camp: counting omissions')+p('以下每组最多算一个缺项。同一问题不重复扣。登记、日志、练习与微课不另计分；无登记但能看到的证据先评，导师提醒补登记。','Each group below counts at most once. Never count the same problem twice. Registration, log, practice and lesson reading carry no separate points; score visible evidence even if registration needs a reminder.')+'<ol>'+''.join('<li>'+bi(*x)+'</li>' for x in units)+'</ol>'+p('四行记录评动作与可检查的说明，不要求截图；六行清单“还不稳”与“扎实”同分。选课维持或更改同分；云盘、邮箱或其他独立备份路线同分；同一设备上另一位置的非同步副本，本周也满足第 4 组。录屏时长约 1 分钟，不设时长扣分。','The four-line record is scored for actions and checkable descriptions; screenshots are not required. “Still shaky” and “solid” inventory entries earn equal credit. Keeping or changing a course earns equal credit, as do cloud, email and other independent backup routes; an unsynced copy in another location on the same device also meets group 4 this week. The tour target is ~1 minute, with no duration deduction.')+h(2,'不计分的共同要求','Shared ungraded requirements')+privacy+independent+p('引用别人介绍配来源；自己的旧记录不必给自己做来源卡。若证据显示代写，按课程学术诚信程序核实，不凭文风猜测。允许修改重交；迟交不扣分。导师收到链接或更新邮件后一周内回复分数与一条建议，两个导师先用同一份样例对齐尺度。','Cite quoted course descriptions; your own prior notes need no source card. If evidence suggests substituted authorship, follow the course’s integrity process; do not infer it from writing style. Revisions are welcome, with no late penalty. Mentors reply with a score and one suggestion within a week of receiving the links or update email; both mentors first calibrate with the same sample.')+p('B6 总分 5 分，属于第一学期数字基本功 B1–B6 共 30 分。','B6 contributes 5 points to Semester 1’s 30-point Digital Basics B1–B6 total.')+links([('index.html','← 任务地图','← Quest map'),('base-camp.html','起点营地 →','Base Camp →')])
write('rubric.html','量规','Rubric',body)
for name,zh,en in [('w7.html','第 7 周从这里开始','Week 7 starts here'),('task-1-workspace-and-choice.html','任务已分成三关','The task now has three tiers')]:
 write(name,zh,en,h(1,zh,en)+p('旧链接继续可用。本周步骤与评分以新的任务地图、关卡页与量规为准。','Your old link still works. Use the new quest map, tier pages and rubric for this week’s steps and scoring.')+links([('index.html','任务地图 →','Quest map →'),('base-camp.html','必做：起点营地 →','Required: Base Camp →'),('rubric.html','评分量规','Scoring rubric')])+'<h2 id="pace">'+bi('建议节奏','Suggested pace')+'</h2>'+p('先完成营地，再决定是否挑战山脊和登顶。不设新日期；大学假期不安排工作，有冲突顺延到下一个工作日。迟交不扣分。','Complete Base Camp, then decide whether to attempt Ridge and Summit. No new dates are set; keep university holidays free and shift conflicts to the next working day. No late penalty.')+faq+nextmod,'signpost')
# Optional expanded explanation of Base Camp setup; not another assignment.
