 if f.name in ['activity-workspace-rehearsal.html','index.html','base-camp.html','ridge.html','summit.html','rubric.html','w7.html','task-1-workspace-and-choice.html']:continue
 s=f.read_text(encoding='utf-8')
 s=re.sub(r'<nav aria-label="Module 本单元">.*?</nav>',nav,s,flags=re.S)
 if 'assets/quest.css' not in s:s=s.replace('</head>','<link rel="stylesheet" href="../../assets/quest.css">\n</head>')
 s=s.replace('href="w7.html"','href="base-camp.html"').replace('href="task-1-workspace-and-choice.html"','href="base-camp.html"')
